// RESUME ACROSS ACCOUNTS: a run id dies with the account, but the slice files on disk do not.
// Pass args = ['S01', 'S04', ...] (the slice ids NOT yet COMPLETE in $SC/walk/) to run only those;
// the critic reads every S*.json on disk regardless. No args = every slice.
const WANT = Array.isArray(args) && args.length ? new Set(args) : null
const NOCRITIC = !!(WANT && WANT.has('--no-critic'))  // a side run (e.g. args ['S20','--no-critic']) must not race the main run's critic on S99.json
const TODO = WANT ? SLICES.filter((s) => WANT.has(s.id)) : SLICES
log(`slices to run: ${TODO.map((s) => s.id).join(' ')}`)
const results = []
let idx = 0
async function worker() {
  while (idx < TODO.length) {
    const k = idx++
    const s = TODO[k]
    log(`▶ ${s.id} ${s.title}`)
    const prompt = `${PREAMBLE}\n\n════ YOUR SLICE: ${s.id} — ${s.title} ════\nStratum lines to read: ${SC}/stratum/full.md lines ${s.lines}.\nWrite your file to ${SC}/walk/${s.id}.json (slice id "${s.id}").\n\nWHAT TO RE-DERIVE, IN PRIORITY ORDER:\n${s.focus}\n\nThen cover every remaining numbered call in your slice's lines at least by reading its cited receipt section and stating RATIFY/AMEND/REVERSE/EVIDENCE-THIN with the evidence you saw.`
    try {
      const r = await agent(prompt, { label: `walk:${s.id}`, phase: 'Verify', schema: SLICE_SCHEMA })
      results[k] = r
      log(`✔ ${s.id} — ${r ? r.calls.length + ' calls' : 'NULL (agent died or was skipped)'}`)
    } catch (e) {
      results[k] = null
      log(`✖ ${s.id} — ${String(e && e.message || e).slice(0, 200)}`)
    }
  }
}
await Promise.all([worker(), worker(), worker(), worker()])

phase('Critic')
const done = results.filter(Boolean)
if (NOCRITIC) {
  const tallyOnly = {}
  for (const r of done) for (const c of r.calls) tallyOnly[c.verdict] = (tallyOnly[c.verdict] || 0) + 1
  log(`--no-critic: skipping the critic; tally ${JSON.stringify(tallyOnly)}`)
  return { tally: tallyOnly, slices: TODO.map((s, i) => ({ id: s.id, returned: !!results[i], calls: results[i] ? results[i].calls.length : 0, summary: results[i] ? results[i].summary : null })), critic: null }
}
const tally = { RATIFY: 0, AMEND: 0, REVERSE: 0, 'EVIDENCE-THIN': 0, 'OUT-OF-SCOPE': 0 }
for (const r of done) for (const c of r.calls) tally[c.verdict] = (tally[c.verdict] || 0) + 1
log(`slices returned ${done.length}/${TODO.length}; tally ${JSON.stringify(tally)}`)
const missing = TODO.filter((s, i) => !results[i]).map((s) => s.id)

const critic = await agent(`${PREAMBLE}\n\n════ YOUR ROLE: COMPLETENESS CRITIC (slice id "S99") ════\nNineteen verifier slices have written their results to ${SC}/walk/S*.json (slices that returned nothing: ${JSON.stringify(missing)}). Read every file there. Then answer, with evidence, as your "calls" entries (use row = the slice id, call = the gap):\n1. COVERAGE: for each ## / ** row heading in ${SC}/stratum/full.md (grep -n '^## §\\|^\\*\\*§\\|^### ' full.md), is there at least one call entry in some slice? List every heading with ZERO entries.\n2. PRIORITY: for each "*What Fable re-derives:*" line in full.md, was its FIRST-named item actually re-derived with CONFIRMED evidence by some slice? List the ones left PLAUSIBLE or untouched, with the settling command the slice named (or your own).\n3. CONTRADICTIONS: where two slices' evidence conflict, or a slice's verdict contradicts a later row's correction (e.g. a RATIFY on a ruling that §884.6/§883.8/§890.1/§888 withdrew), name them.\n4. REVERSALS and AMENDS: list every REVERSE and AMEND across all slices in one table (slice, row, call, one-line reason) so the chair can rule on them in one sitting.\n5. FINDINGS BEYOND THE ROWS: consolidate every slice's "beyond" and "chair_errors" lists, de-duplicated, ranked by consequence (HIGH = touches the live §891 train, a landed defect, THE PROMISE, or an owner decision; MEDIUM = a register/instrument; LOW = process).\n6. PORCELAIN: any slice reporting porcelain_unchanged=false, or a dock any slice says it found dirty — list with the paths.\nDo not re-verify the slices' work yourself beyond spot-checking two HIGH RATIFY claims of your choice (say which and what you found). Write ${SC}/walk/S99.json as you go.`, { label: 'critic', phase: 'Critic', schema: SLICE_SCHEMA })

return { tally, slices: TODO.map((s, i) => ({ id: s.id, returned: !!results[i], calls: results[i] ? results[i].calls.length : 0, summary: results[i] ? results[i].summary : null })), critic }